1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { getSettingInt } from "./settings";
7	import { addMonths } from "./billing-terms";
8	import { debitWallet, InsufficientBalanceError } from "./wallet";
9	
10	// Block storage volumes: add-on disks a customer can order, then attach to /
11	// detach from one of their running servers. A volume is billed per GB / month.
12	// The physical Proxmox disk only exists once a volume has been attached at least
13	// once; `Volume.diskName` tracks where that disk currently lives on the VM
14	// (`scsiN` while attached, `unusedN` while detached) and `Volume.serverId` the
15	// VM that physically holds it. See worker/volumes.ts for the Proxmox side.
16	
17	const MIN_GB = 1;
18	const MAX_GB = 2000;
19	
20	/** Price (in cents) for a volume of `sizeGB`, per-GB/month from Settings. */
21	export async function volumePriceCents(sizeGB: number): Promise<number> {
22	  const perGb = await getSettingInt("volume_price_cents_per_gb", 10);
23	  return Math.max(0, Math.round(sizeGB)) * perGb;
24	}
25	
26	async function ownedVolume(volumeId: string) {
27	  const user = await requireUser();
28	  const volume = await db.volume.findUnique({ where: { id: volumeId } });
29	  if (!volume) throw new Error("Not found");
30	  if (volume.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
31	  return { user, volume };
32	}
33	
34	async function ownedServer(serverId: string) {
35	  const user = await requireUser();
36	  const server = await db.server.findUnique({ where: { id: serverId } });
37	  if (!server) throw new Error("Not found");
38	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
39	  return { user, server };
40	}
41	
42	/** Reject if the server already has a job queued or running (one in-flight per server). */
43	async function serverBusy(serverId: string): Promise<boolean> {
44	  const pending = await db.job.count({
45	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
46	  });
47	  return pending > 0;
48	}
49	
50	/**
51	 * Order a new block storage volume: debit the wallet up-front (one month) and
52	 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
53	 * DETACHED (available to attach). No physical disk is created until attach.
54	 */
55	export async function orderVolume(
56	  name: string,
57	  sizeGB: number
58	): Promise<{ error?: string; id?: string }> {
59	  const user = await requireUser();
60	
61	  const clean = (name ?? "")
62	    .replace(/[\x00-\x1f\x7f]/g, "")
63	    .replace(/\s+/g, " ")
64	    .trim();
65	  if (clean.length < 2 || clean.length > 40) {
66	    return { error: "Name must be 2–40 characters." };
67	  }
68	  const size = Math.round(Number(sizeGB));
69	  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
70	    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
71	  }
72	
73	  const priceCents = await volumePriceCents(size);
74	
75	  let volumeId: string;
76	  try {
77	    volumeId = await db.$transaction(async (tx) => {
78	      await debitWallet(tx, user.id, priceCents);
79	      await tx.walletTransaction.create({
80	        data: {
81	          userId: user.id,
82	          amountCents: -priceCents,
83	          description: `Block storage volume: ${clean} (${size} GB)`,
84	        },
85	      });
86	      const v = await tx.volume.create({
87	        data: {
88	          userId: user.id,
89	          name: clean,
90	          sizeGB: size,
91	          priceCents,
92	          status: "PENDING",
93	          expiresAt: addMonths(new Date(), 1),
94	        },
95	      });
96	      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
97	      return v.id;
98	    });
99	  } catch (e) {
100	    if (e instanceof InsufficientBalanceError) {
101	      return { error: "Insufficient balance — top up your wallet first." };
102	    }
103	    throw e;
104	  }
105	
106	  await db.auditLog.create({
107	    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
108	  });
109	  revalidatePath("/dashboard/volumes");
110	  return { id: volumeId };
111	}
112	
113	/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
114	export async function attachVolume(
115	  volumeId: string,
116	  serverId: string
117	): Promise<{ error?: string }> {
118	  const { user, volume } = await ownedVolume(volumeId);
119	  const { server } = await ownedServer(serverId);
120	
121	  if (volume.status !== "DETACHED") {
122	    return { error: "Only an available (detached) volume can be attached." };
123	  }
124	  if (!server.vmid || server.status !== "RUNNING") {
125	    return { error: "Target server must be running." };
126	  }
127	  // A volume that already holds data physically lives on one server's VM; it can
128	  // only be re-attached there (cross-node disk migration is out of scope).
129	  if (volume.serverId && volume.serverId !== serverId) {
130	    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
131	  }
132	  if (await serverBusy(serverId)) {
133	    return { error: "Another operation is already in progress on this server." };
134	  }
135	
136	  await db.volume.update({ where: { id: volumeId }, data: { serverId } });
137	  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
138	  await db.auditLog.create({
139	    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
140	  });
141	  revalidatePath("/dashboard/volumes");
142	  revalidatePath(`/dashboard/servers/${serverId}`);
143	  return {};
144	}
145	
146	/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
147	export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
148	  const { user, volume } = await ownedVolume(volumeId);
149	  if (volume.status !== "ATTACHED" || !volume.serverId) {
150	    return { error: "Volume is not attached." };
151	  }
152	  if (await serverBusy(volume.serverId)) {
153	    return { error: "Another operation is already in progress on this server." };
154	  }
155	  await db.job.create({
156	    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
157	  });
158	  await db.auditLog.create({
159	    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
160	  });
161	  revalidatePath("/dashboard/volumes");
162	  revalidatePath(`/dashboard/servers/${volume.serverId}`);
163	  return {};
164	}
165	
166	/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
167	export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
168	  const { user, volume } = await ownedVolume(volumeId);
169	  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };
170	
171	  // If the disk physically lives on a server, route the delete through it and
172	  // honour the one-in-flight-job guard so we don't collide with another op.
173	  if (volume.serverId) {
174	    if (await serverBusy(volume.serverId)) {
175	      return { error: "Another operation is already in progress on this server." };
176	    }
177	  }
178	  await db.volume.update({ where: { id: volumeId }, data: { status: "DELETING" } });
179	  await db.job.create({
180	    data: {
181	      type: "VOLUME_DELETE",
182	      serverId: volume.serverId ?? undefined,
183	      payload: { volumeId },
184	    },
185	  });
186	  await db.auditLog.create({
187	    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
188	  });
189	  revalidatePath("/dashboard/volumes");
190	  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
191	  return {};
192	}
