1	import { db } from "../lib/db";
2	import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
3	import { SANDBOX } from "../lib/sandbox";
4	import type { Job } from "@prisma/client";
5	
6	/**
7	 * Block storage volume handlers (add-on disks attached to a VPS).
8	 *
9	 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
10	 *   VOLUME_CREATE: volumeCreate,
11	 *   VOLUME_ATTACH: volumeAttach,
12	 *   VOLUME_DETACH: volumeDetach,
13	 *   VOLUME_DELETE: volumeDelete,
14	 *
15	 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
16	 * so these handlers trust `payload.volumeId`.
17	 *
18	 * A volume's underlying Proxmox disk only exists once it has been attached at
19	 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
20	 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
21	 * changes across detach/re-attach; we always re-scan the VM config to find the
22	 * disk's current key (scsiN while attached, unusedN while detached).
23	 */
24	
25	async function loadVolume(job: Job) {
26	  const payload = (job.payload ?? {}) as { volumeId?: string };
27	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
28	  const volume = await db.volume.findUnique({
29	    where: { id: payload.volumeId },
30	    include: { server: { include: { node: true } } },
31	  });
32	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
33	  return volume;
34	}
35	
36	/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
37	async function nodeFor(server: any) {
38	  const n =
39	    server?.node ??
40	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
41	    (await db.node.findFirst({ where: { enabled: true } }));
42	  if (!n) {
43	    return {
44	      conn: {
45	        get: pve.get,
46	        post: pve.post,
47	        put: pve.put,
48	        del: pve.del,
49	        node: envNode,
50	        waitForTask,
51	        nextVmid,
52	        vmStatus,
53	      } as any,
54	      row: null,
55	    };
56	  }
57	  return {
58	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
59	    row: n,
60	  };
61	}
62	
63	async function notify(userId: string, title: string, body?: string, href?: string) {
64	  try {
65	    await db.notification.create({ data: { userId, title, body, href } });
66	  } catch (e) {
67	    console.error("[volumes] notify failed", e);
68	  }
69	}
70	
71	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
72	function volidOf(configValue: unknown): string {
73	  return String(configValue ?? "").split(",")[0].trim();
74	}
75	
76	/**
77	 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
78	 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
79	 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
80	 */
81	function isRealVolid(v: unknown): v is string {
82	  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
83	}
84	
85	/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
86	function diskVolids(config: Record<string, any>): string[] {
87	  const out: string[] = [];
88	  for (const [k, v] of Object.entries(config)) {
89	    if (typeof v !== "string") continue;
90	    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
91	    const id = volidOf(v);
92	    if (isRealVolid(id)) out.push(id);
93	  }
94	  return out;
95	}
96	
97	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
98	function freeScsiSlot(config: Record<string, any>): string {
99	  for (let i = 1; i <= 30; i++) {
100	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
101	  }
102	  throw new Error("no free scsi slot available on this VM");
103	}
104	
105	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
106	function keyForVolid(config: Record<string, any>, volid: string): string | null {
107	  for (const [k, v] of Object.entries(config)) {
108	    if (typeof v === "string" && volidOf(v) === volid) return k;
109	  }
110	  return null;
111	}
112	
113	/**
114	 * VOLUME_CREATE — logical registration only. No physical disk is created until
115	 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
116	 * from PENDING to DETACHED so the customer can attach it.
117	 */
118	export async function volumeCreate(job: Job): Promise<void> {
119	  const volume = await loadVolume(job);
120	  if (volume.status === "PENDING") {
121	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
122	  }
123	  await notify(
124	    volume.userId,
125	    `Volume "${volume.name}" is ready`,
126	    `${volume.sizeGB} GB block storage is available to attach to a server.`,
127	    "/dashboard/volumes"
128	  );
129	}
130	
131	/**
132	 * VOLUME_ATTACH — attach the disk to the target server's VM at a free scsi slot.
133	 * Creates the underlying disk on first attach ("<storage>:<sizeGB>"); on a
134	 * re-attach it re-uses the existing volume id so data is preserved.
135	 */
136	export async function volumeAttach(job: Job): Promise<void> {
137	  const volume = await loadVolume(job);
138	  const server = volume.server;
139	  if (SANDBOX) {
140	    // Simulate the attach with a synthetic disk id — no Proxmox config read/write.
141	    await db.volume.update({
142	      where: { id: volume.id },
143	      data: { status: "ATTACHED", serverId: server?.id ?? null, diskName: `sandbox:vol-${volume.id}` },
144	    });
145	    await notify(
146	      volume.userId,
147	      `Volume "${volume.name}" attached${server ? ` to ${server.hostname}` : ""}`,
148	      `${volume.sizeGB} GB is now available (sandbox). Format and mount it inside the server to use it.`,
149	      server ? `/dashboard/servers/${server.id}` : "/dashboard/volumes"
150	    );
151	    return;
152	  }
153	  if (!server || !server.vmid) throw new Error("volume attach: server has no VM");
154	
155	  const { conn, row } = await nodeFor(server);
156	  const storage = row?.storageNvme ?? "vmdata";
157	
158	  const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
159	  const slot = freeScsiSlot(config);
160	  // Snapshot the disks the VM already owns so we can identify a freshly-created
161	  // one by diff if the slot read-back is unusable (see fallback below).
162	  const before = new Set(diskVolids(config));
163	
164	  // Re-use the existing disk (by volid) if this volume was attached before;
165	  // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
166	  const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
167	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { [slot]: source });
168	
169	  // Record the STABLE volid (vmdata:vm-<vmid>-disk-N) so detach/re-attach and the
170	  // reinstall data-safety guard can find this disk later. This MUST NOT be left
171	  // null: derive it with layered fallbacks rather than trusting a single read.
172	  // Proxmox applies a config POST ASYNCHRONOUSLY — an immediate GET can still
173	  // return the pre-write view, leaving both the slot and the "appeared" diff
174	  // empty. That race is exactly how volumes ended up with a null diskName.
175	  // Poll briefly for the write to land before falling through to the fallbacks.
176	  let after = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
177	  for (let i = 0; i < 10 && !isRealVolid(volidOf(after[slot])); i++) {
178	    await new Promise((r) => setTimeout(r, 1000));
179	    after = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
180	  }
181	  let volid: string | null = null;
182	  // 1) Preferred: the volid Proxmox kept/created at the slot we just wrote.
183	  const atSlot = volidOf(after[slot]);
184	  if (isRealVolid(atSlot)) {
185	    volid = atSlot;
186	  } else if (volume.diskName && isRealVolid(volume.diskName)) {
187	    // 2) Re-attach path: the disk we asked to attach is a known-good volid.
188	    volid = volume.diskName;
189	  } else {
190	    // 3) First-attach path where the slot read-back didn't yield a volid (pending
191	    //    config view, momentary omission, …): identify the disk that newly appeared.
192	    const appeared = diskVolids(after).filter((v) => !before.has(v));
193	    if (appeared.length === 1) volid = appeared[0];
194	  }
195	
196	  await db.volume.update({
197	    where: { id: volume.id },
198	    // Never regress a previously-recorded good volid to null on a retry.
199	    data: { status: "ATTACHED", serverId: server.id, diskName: volid ?? volume.diskName ?? null },
200	  });
201	  await notify(
202	    volume.userId,
203	    `Volume "${volume.name}" attached to ${server.hostname}`,
204	    `${volume.sizeGB} GB is now available as ${slot}. Format and mount it inside the server to use it.`,
205	    `/dashboard/servers/${server.id}`
206	  );
207	}
208	
209	/**
210	 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
211	 * entry, preserving the data). The volume stays pinned to this server so it can
212	 * be re-attached here later.
213	 */
214	export async function volumeDetach(job: Job): Promise<void> {
215	  const volume = await loadVolume(job);
216	  const server = volume.server;
217	
218	  if (SANDBOX) {
219	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
220	    if (server) {
221	      await notify(
222	        volume.userId,
223	        `Volume "${volume.name}" detached from ${server.hostname}`,
224	        "The volume and its data are preserved and can be re-attached (sandbox).",
225	        "/dashboard/volumes"
226	      );
227	    }
228	    return;
229	  }
230	
231	  if (server?.vmid && volume.diskName) {
232	    const { conn } = await nodeFor(server);
233	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
234	    const key = keyForVolid(config, volume.diskName);
235	    if (key && key.startsWith("scsi")) {
236	      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
237	    }
238	  }
239	
240	  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
241	  if (server) {
242	    await notify(
243	      volume.userId,
244	      `Volume "${volume.name}" detached from ${server.hostname}`,
245	      "The volume and its data are preserved and can be re-attached to the same server.",
246	      "/dashboard/volumes"
247	    );
248	  }
249	}
250	
251	/**
252	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
253	 * disk, and remove the Volume row.
254	 */
255	export async function volumeDelete(job: Job): Promise<void> {
256	  const volume = await loadVolume(job);
257	  const server = volume.server;
258	
259	  if (SANDBOX) {
260	    await db.volume.delete({ where: { id: volume.id } });
261	    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
262	    return;
263	  }
264	
265	  if (server?.vmid && volume.diskName) {
266	    const { conn } = await nodeFor(server);
267	    try {
268	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
269	      let key = keyForVolid(config, volume.diskName);
270	
271	      // If still mounted, detach to an "unused" entry first.
272	      if (key && key.startsWith("scsi")) {
273	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
274	        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
275	        key = keyForVolid(config, volume.diskName);
276	      }
277	      // Deleting an "unused" entry destroys the underlying disk.
278	      if (key) {
279	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
280	      }
281	    } catch (e: any) {
282	      const msg = String(e?.body ?? e?.message ?? e);
283	      if (!msg.includes("does not exist")) throw e;
284	    }
285	  }
286	
287	  await db.volume.delete({ where: { id: volume.id } });
288	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
289	}
