1	"use client";
2	
3	import { useMemo, useState, useTransition } from "react";
4	import { StatusDot, fmtMoney } from "@/components/ui/primitives";
5	import {
6	  orderVolume,
7	  attachVolume,
8	  detachVolume,
9	  deleteVolume,
10	} from "@/lib/actions-volumes";
11	
12	export type VolumeRow = {
13	  id: string;
14	  name: string;
15	  sizeGB: number;
16	  priceCents: number;
17	  status: string;
18	  serverId: string | null;
19	  serverName: string | null;
20	};
21	
22	export type ServerOption = { id: string; hostname: string };
23	
24	/** Volume states in which no attach/detach/delete action should be offered. */
25	function isBusy(status: string): boolean {
26	  return status === "PENDING" || status === "DELETING";
27	}
28	
29	function StatusLabel({ status }: { status: string }) {
30	  return <StatusDot status={status} />;
31	}
32	
33	// ---------------------------------------------------------------------------
34	// Create form
35	// ---------------------------------------------------------------------------
36	
37	function CreateVolume({ perGbCents }: { perGbCents: number }) {
38	  const [name, setName] = useState("");
39	  const [size, setSize] = useState(10);
40	  const [error, setError] = useState<string | null>(null);
41	  const [pending, start] = useTransition();
42	
43	  const monthly = Math.max(0, Math.round(size)) * perGbCents;
44	
45	  return (
46	    <div className="card p-5">
47	      <h3 className="text-base font-semibold">New volume</h3>
48	      <p className="mt-1 text-sm text-slate-400">
49	        Order an add-on disk, then attach it to any of your running servers.
50	      </p>
51	      <div className="mt-4 flex flex-wrap items-end gap-3">
52	        <div>
53	          <label className="label">Name</label>
54	          <input
55	            className="input w-56"
56	            value={name}
57	            onChange={(e) => setName(e.target.value)}
58	            placeholder="data-disk"
59	            maxLength={40}
