3	import { useState, useTransition } from "react";
4	import { resizeServerDown } from "@/lib/actions-server-lifecycle";
5	import { fmtMoney } from "@/components/ui/primitives";
6	import { vpsTermPriceCents, addMonths } from "@/lib/billing-terms";
7	
8	type PlanRow = {
9	  id: string;
10	  name: string;
11	  cpuCores: number;
12	  ramMB: number;
13	  diskGB: number;
