17	
18	export function ResizeDown({
19	  serverId,
20	  currentPlanId,
21	  currentDiskGB,
22	  currentPriceCents,
23	  termMonths,
24	  expiresAt,
25	  isFree,
26	  plans,
27	  disabled,
28	}: {
29	  serverId: string;
30	  currentPlanId: string;
31	  currentDiskGB: number;
32	  currentPriceCents: number;
33	  termMonths: number;
34	  /** ISO string of the current term end, or null */
35	  expiresAt: string | null;
36	  isFree: boolean;
37	  plans: PlanRow[];
38	  disabled?: boolean;
39	}) {
40	  const [selected, setSelected] = useState<string | null>(null);
41	  const [error, setError] = useState<string | null>(null);
42	  const [pending, start] = useTransition();
43	
44	  // Only cheaper plans are downgrade candidates.
45	  const smaller = plans.filter((p) => p.id !== currentPlanId && p.priceCents < currentPriceCents);
46	  const target = smaller.find((p) => p.id === selected) ?? null;
47	
48	  // Estimated prorated credit (mirrors resizeServerDown on the server).
49	  function estimateCredit(newPriceCents: number): number {
50	    if (isFree || !expiresAt) return 0;
51	    const end = new Date(expiresAt).getTime();
52	    const periodStart = addMonths(new Date(expiresAt), -termMonths).getTime();
53	    const periodMs = end - periodStart;
54	    const remainingFraction =
55	      periodMs > 0 ? Math.max(0, Math.min(1, (end - Date.now()) / periodMs)) : 0;
56	    const deltaFullTerm =
57	      vpsTermPriceCents(currentPriceCents, termMonths) - vpsTermPriceCents(newPriceCents, termMonths);
58	    return Math.max(0, Math.round(deltaFullTerm * remainingFraction));
59	  }
60	
61	  const credit = target ? estimateCredit(target.priceCents) : 0;
62	
63	  return (
64	    <div className="card space-y-5">
65	      <div>
66	        <h2 className="font-semibold">Downsize your plan</h2>
