68	          Move to a smaller, cheaper plan. CPU and RAM shrink on the next power cycle. Disk storage
69	          can&apos;t shrink, so only plans whose disk is at least your current {currentDiskGB} GB are
70	          selectable. We credit the prorated difference for the rest of your term back to your
71	          wallet.
72	        </p>
73	      </div>
74	
75	      {error && (
76	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
77	          {error}
78	        </div>
79	      )}
80	
81	      {smaller.length === 0 ? (
82	        <p className="text-sm text-slate-400">
83	          You&apos;re already on the smallest plan — there&apos;s nothing smaller to move to.
84	        </p>
85	      ) : (
86	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
87	          {smaller.map((p) => {
88	            const diskShrinks = p.diskGB < currentDiskGB;
