104	                    : active
105	                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
106	                      : "cursor-pointer hover:border-white/20"
107	                }`}
108	              >
109	                <div className="flex items-baseline justify-between">
110	                  <span className="font-semibold">{p.name}</span>
111	                  <span className="text-lg font-bold">
112	                    {fmtMoney(p.priceCents)}
113	                    <span className="text-xs font-normal text-slate-400">/mo</span>
114	                  </span>
115	                </div>
116	                <p className="mt-1 text-sm text-slate-400">
117	                  {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
118	                </p>
119	                {diskShrinks && (
120	                  <p className="mt-2 text-xs text-slate-500">Smaller disk — can&apos;t shrink</p>
121	                )}
122	              </button>
123	            );
124	          })}
125	        </div>
126	      )}
127	
128	      {smaller.length > 0 && (
129	        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
130	          <p className="text-xs text-slate-400">
131	            {target && credit > 0 ? (
132	              <>
133	                Estimated credit back to your wallet:{" "}
134	                <span className="font-semibold text-emerald-400">{fmtMoney(credit)}</span>. Requires a
135	                power cycle.
136	              </>
137	            ) : (
138	              "Downsizing requires a power cycle. The new price applies at your next renewal."
139	            )}
140	          </p>
141	          <button
142	            className="btn-primary"
143	            disabled={!target || pending || disabled}
144	            onClick={() => {
145	              if (!target) return;
146	              if (
147	                !window.confirm(
148	                  `Downsize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)?${
149	                    credit > 0 ? ` ${fmtMoney(credit)} will be credited to your wallet.` : ""
150	                  } The server will be power-cycled.`
151	                )
152	              )
153	                return;
154	              start(async () => {
155	                setError(null);
156	                const res = await resizeServerDown(serverId, target.id);
157	                if (res?.error) setError(res.error);
158	                else setSelected(null);
159	              });
160	            }}
161	          >
162	            {pending ? "Downsizing…" : target ? `Downsize to ${target.name}` : "Select a plan"}
163	          </button>
164	        </div>
165	      )}
166	    </div>
167	  );
168	}
