87	/**
88	 * Validate an expansion and compute the prorated charge over the ACTUAL
89	 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
90	 * remaining month; null expiresAt on free/admin servers => 0). Throws
91	 * DiskExpandError with a user-facing message on any guard failure. Does NOT
92	 * check ownership — callers must do that.
93	 */
94	export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
95	  const server = await loadServer(serverId);
96	  if (!server) throw new DiskExpandError("Not found");
97	  if (!isValidExtraDiskAddGB(addGB)) {
98	    throw new DiskExpandError(
99	      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
100	    );
101	  }
102	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
103	    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
104	  }
105	  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");
106	
107	  const targetExtraDiskGB = server.extraDiskGB + addGB;
108	  const newTotalDiskGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
109	  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
110	    throw new DiskExpandError(
111	      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
112	    );
113	  }
114	
115	  // Don't sell space the node can't physically back.
116	  const cap = await diskCapacityCheck(server.nodeId, addGB);
117	  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");
118	
119	  const perGbCents = await extraDiskPerGbCents();
120	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
121	
122	  let prorateCents = 0;
123	  if (!server.isFree && server.expiresAt) {
124	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - Date.now()) / MS_PER_AVG_MONTH);
125	    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths));
126	  }
127	  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
128	}
