15	/**
16	 * Per-server DISK EXPANSION handler (JobType.DISK_EXPAND).
17	 *
18	 * Grows ONE server's own root disk by N GB — the plan's CPU/RAM are untouched.
19	 * Payment already happened at enqueue time (lib/disk-expand.ts applyDiskExpand),
20	 * so this handler trusts `payload.addGB` / `payload.targetExtraDiskGB` and is
21	 * responsible only for delivering the space.
22	 *
23	 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there
24	 * as `DISK_EXPAND: diskExpand`. It must NOT be listed in VM_STATE_FAILURE_JOBS:
25	 * growing a disk never changes the VM's run state, so a failure must not strand
26	 * the server in ERROR (see the note in worker/index.ts).
27	 *
28	 * ─── SEQUENCE ───────────────────────────────────────────────────────────────
29	 *   1. read the VM config, work out the CURRENT scsi0 size
30	 *   2. if it is already >= the target, SKIP Proxmox entirely (idempotent retry)
31	 *      otherwise PUT .../resize with size=+<delta>G  (Proxmox only ever grows)
32	 *   3. online-grow the guest: rescan the device, growpart the root partition,
33	 *      then resize2fs / xfs_growfs / btrfs resize depending on the fs type
34	 *   4. persist Server.extraDiskGB and notify
35	 *
36	 * ─── RETRY SAFETY ───────────────────────────────────────────────────────────
37	 * Every step is idempotent. A retry after a crash mid-way re-reads the real disk
38	 * size from Proxmox, skips work already done, and re-runs the guest grow (which
39	 * is a no-op — growpart reports NOCHANGE and resize2fs "nothing to do").
40	 *
41	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
42	 * Proxmox refuses to shrink a disk and so do we: the delta is always positive and
43	 * `Server.extraDiskGB` is only ever raised.
44	 *
45	 * ─── THE CUSTOMER NEVER PAYS FOR INVISIBLE SPACE ────────────────────────────
46	 * If the guest grow can't be done online (server stopped, unreachable, LVM/exotic
47	 * layout, missing tools) the disk is STILL bigger — so this is NOT treated as a
48	 * failure. The job completes and the notification spells out the exact commands
49	 * to run, rather than leaving the customer paying for space they can't see.
50	 */
51	
52	/** Root device paths are the only thing we ever interpolate — keep them inert. */
53	const DEV_PATH_RE = /^\/dev\/[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$/;
54	/** A bare kernel block-device name, e.g. "sda", "vda", "nvme0n1". */
55	const DEV_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/;
56	/** A partition number, 1–99. */
57	const PARTNUM_RE = /^[1-9][0-9]?$/;
58	/** Filesystems we know how to grow online. */
59	const GROWABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
60	
61	/** Best-effort live progress write onto the running Job row (never throws). */
