81	/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
82	async function nodeFor(server: any) {
83	  const n =
84	    server?.node ??
85	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
86	    (await db.node.findFirst({ where: { enabled: true } }));
87	  if (!n) {
88	    return {
89	      conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node: envNode, waitForTask, nextVmid, vmStatus } as any,
90	      row: null,
91	    };
92	  }
93	  return {
94	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
