119	type GuestLayout = {
120	  rootDevice: string;   // /dev/sda1
121	  fsType: string;       // ext4 | xfs | …
122	  parentName: string;   // sda
123	  partNum: string;      // 1
124	};
125	
126	/**
127	 * Read the guest's root-filesystem layout with a single READ-ONLY command
128	 * (fixed string — nothing is interpolated), then validate every field against a
129	 * shell-inert allowlist before it is ever used in a mutating command. We reject
130	 * rather than sanitize, exactly like lib/ssh-exec.ts.
131	 */
132	async function detectLayout(conn: Client): Promise<GuestLayout | { error: string }> {
133	  const probe = [
134	    'ROOT="$(findmnt -nro SOURCE / 2>/dev/null | head -n1)"',
135	    'FSTYPE="$(findmnt -nro FSTYPE / 2>/dev/null | head -n1)"',
136	    'BASE="$(basename "$ROOT" 2>/dev/null)"',
137	    'PARENT="$(lsblk -nro PKNAME "$ROOT" 2>/dev/null | head -n1)"',
138	    'PARTNUM="$(cat "/sys/class/block/$BASE/partition" 2>/dev/null || echo "")"',
139	    'echo "ROOT=$ROOT"; echo "FSTYPE=$FSTYPE"; echo "PARENT=$PARENT"; echo "PARTNUM=$PARTNUM"',
140	  ].join("; ");
141	  const res = await exec(conn, probe, QUICK_TIMEOUT_MS);
142	  const get = (k: string) =>
143	    (new RegExp(`^${k}=(.*)$`, "m").exec(res.stdout)?.[1] ?? "").trim();
144	
145	  const rootDevice = get("ROOT");
146	  const fsType = get("FSTYPE").toLowerCase();
147	  const parentName = get("PARENT");
148	  const partNum = get("PARTNUM");
149	
150	  if (!DEV_PATH_RE.test(rootDevice)) {
151	    return { error: `could not identify the root device (got "${rootDevice.slice(0, 40)}")` };
152	  }
153	  if (!GROWABLE_FS.has(fsType)) {
154	    return { error: `unsupported root filesystem "${fsType.slice(0, 20) || "unknown"}"` };
155	  }
156	  // LVM / device-mapper roots need pvresize + lvextend, which we will not
157	  // attempt unattended on live customer data — hand over exact instructions.
158	  if (rootDevice.startsWith("/dev/mapper/") || /^dm-\d+$/.test(parentName)) {
159	    return { error: "the root filesystem is on LVM" };
160	  }
161	  if (!DEV_NAME_RE.test(parentName)) {
162	    return { error: `could not identify the parent disk of ${rootDevice}` };
163	  }
164	  if (!PARTNUM_RE.test(partNum)) {
165	    return { error: `could not identify the partition number of ${rootDevice}` };
166	  }
167	  return { rootDevice, fsType, parentName, partNum };
168	}
169	
170	/** The exact commands a customer (or support) can run to finish the job by hand. */
171	function manualCommands(layout: GuestLayout | null): string {
172	  if (layout) {
173	    return [
174	      `growpart /dev/${layout.parentName} ${layout.partNum}`,
175	      layout.fsType === "xfs"
176	        ? "xfs_growfs /"
177	        : layout.fsType === "btrfs"
178	          ? "btrfs filesystem resize max /"
179	          : `resize2fs ${layout.rootDevice}`,
180	    ].join(" && ");
181	  }
182	  return (
183	    "ROOT=$(findmnt -nro SOURCE /); PARENT=/dev/$(lsblk -nro PKNAME \"$ROOT\"); " +
184	    "PART=$(cat /sys/class/block/$(basename \"$ROOT\")/partition); " +
185	    "growpart \"$PARENT\" \"$PART\" && (resize2fs \"$ROOT\" || xfs_growfs /)"
186	  );
187	}
