async function mountExtraFs(conn: Client, devPath: string): Promise<{ ok: boolean; detail: string }> {
  if (!DEVPATH_RE.test(devPath)) return { ok: false, detail: "device path failed validation" };
  const bl = await sh(conn, `blkid -s UUID -o value ${devPath} 2>/dev/null`);
  const uuid = clean(bl.stdout, 64);
  if (!UUID_RE.test(uuid)) return { ok: false, detail: "could not read a valid filesystem UUID" };

  await sh(conn, `mkdir -p ${EXTRA_DISK_MOUNT}`);
  await sh(
    conn,
    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s ext4 defaults,nofail 0 2\\n' '${uuid}' '${EXTRA_DISK_MOUNT}' >> /etc/fstab`
  );
  const mnt = await sh(
    conn,
    `mountpoint -q ${EXTRA_DISK_MOUNT} || mount ${EXTRA_DISK_MOUNT} 2>&1 || mount ${devPath} ${EXTRA_DISK_MOUNT} 2>&1`,
    SETUP_TIMEOUT_MS
  );
  const mounted = await shOk(conn, `mountpoint -q ${EXTRA_DISK_MOUNT}`);
  if (!mounted) return { ok: false, detail: `mount failed: ${tailOf(mnt)}` };
  return { ok: true, detail: `mounted at ${EXTRA_DISK_MOUNT} (fstab UUID entry, nofail)` };
}

/** Format + persistently mount ONE blank disk at EXTRA_DISK_MOUNT. Idempotent. */
async function prepareExtraDisk(conn: Client, dev: string): Promise<{ ok: boolean; detail: string }> {
  if (!BLOCKDEV_RE.test(dev)) return { ok: false, detail: "device name failed validation" };
  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data /dev/${dev} 2>&1`, INSTALL_TIMEOUT_MS);
  if (mk.code !== 0) return { ok: false, detail: `mkfs.ext4 failed: ${tailOf(mk)}` };
  const m = await mountExtraFs(conn, `/dev/${dev}`);
  if (!m.ok) return m;
  return { ok: true, detail: `formatted ext4 and ${m.detail}` };
}

