        // Low-pool alert, gated by the Settings toggle. (Auto-ordering IPs spends
        // real money via OVH and is intentionally left as a manual admin action.)
        const { getSettingBool, getSettingInt } = await import("../lib/settings");
        if (await getSettingBool("dedicated_ip_autoreplenish", false)) {
          const free = await db.dedicatedIp.count({ where: { status: "FREE" } });
          const threshold = await getSettingInt("dedicated_ip_replenish_threshold", 2);
          if (free < threshold) {
            const recent = await db.notification.findFirst({
              where: { title: { contains: "Dedicated IP pool low" }, createdAt: { gt: new Date(Date.now() - 6 * 3600_000) } },
            });
            if (!recent) {
              const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
              await db.notification.createMany({
                data: admins.map((a) => ({
                  userId: a.id,
                  title: `Dedicated IP pool low (${free} free)`,
                  body: `Free dedicated IPs (${free}) fell below the replenish threshold (${threshold}). Order more failover IPs from OVH, then the pool auto-imports on the next sync.`,
                  href: "/admin/ips",
                })),
              });
            }
          }
        }
      } catch (e) {
        console.error("[worker] IP pool sync error", e);
      }
    }
    try {
      const candidate = await db.job.findFirst({
        where: { status: "QUEUED" },
        orderBy: { createdAt: "asc" },
      });
      if (candidate) {
        // Atomic claim: only the worker whose updateMany matches the still-QUEUED
        // row wins. If count===0 another worker (or a retry) already took it, so we
        // skip and re-poll — prevents the same job running twice under concurrency.
        const claim = await db.job.updateMany({
          where: { id: candidate.id, status: "QUEUED" },
          data: { status: "RUNNING", attempts: { increment: 1 } },
        });
        if (claim.count === 1) {
          const claimed = await db.job.findUnique({ where: { id: candidate.id } });
          if (claimed) await runJob(claimed);
        }
        // else: lost the race — loop immediately to grab the next queued job.
      } else {
        await new Promise((r) => setTimeout(r, POLL_MS));
      }
    } catch (e) {
      console.error("[worker] loop error", e);
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  }
}

